RULES = [
 {"h": "i before e, except after c", "body": "Write <b>ie</b> when the sound is 'ee': believe, achieve, field, piece. After <b>c</b> write <b>ei</b>: receive, ceiling, deceive. Write <b>ei</b> when it sounds like 'ay': eight, weight, neighbour, vein.", "ex": ["believe", "receive", "ceiling", "piece", "eight"], "warn": "Exceptions to learn by heart: weird, seize, either, neither, foreign, height, leisure, protein, science, species."},
 {"h": "Doubling the final consonant", "body": "Double the last consonant before <b>-ed, -ing, -er</b> when the word ends in <b>one vowel + one consonant</b> and the stress is on the last syllable: stop → stopped, begin → beginning, prefer → preferred, occur → occurred. If the stress is not on the last syllable, don't double: visit → visited, open → opening, happen → happened, benefit → benefited.", "ex": ["stopped", "beginning", "preferred", "occurred", "visited", "happened"], "warn": "British English always doubles a final l after a short vowel: travel → travelling, cancel → cancelled (American: traveling, canceled)."},
 {"h": "Dropping the silent e", "body": "Drop the final silent <b>e</b> before a suffix that starts with a vowel: make → making, write → writing, hope → hoping, use → usable. Keep it before a consonant suffix: hope → hopeful, use → useless, complete → completely, sincere → sincerely.", "ex": ["writing", "hoping", "completely", "hopeful", "usable"], "warn": "Keep the e after c or g to keep the sound soft: noticeable, manageable, courageous. Exceptions: argument, truly, ninth, wholly."},
 {"h": "y becomes i", "body": "After a consonant, <b>y</b> changes to <b>i</b> before most suffixes: happy → happiness, carry → carried, study → studies, easy → easily. After a vowel, keep the y: play → played, enjoy → enjoyment.", "ex": ["happiness", "carried", "studies", "easily", "played"], "warn": "Keep the y before -ing: studying, carrying, flying."},
 {"h": "-able or -ible?", "body": "If you can remove <b>-able</b> and still have a complete word, it's usually -able: accept → acceptable, depend → dependable, understand → understandable. If the root isn't a word on its own, it's often <b>-ible</b>: visible, possible, terrible, edible, horrible.", "ex": ["acceptable", "dependable", "visible", "possible", "responsible"], "warn": "Learn the exceptions as you meet them: responsible, sensible, flexible (-ible), and probable, capable (-able)."},
 {"h": "-ance / -ence, -ant / -ent", "body": "There is no reliable sound rule, but there are clues: words from verbs ending in <b>-ere</b> or <b>-ist</b> often take <b>-ence</b>: interfere → interference, exist → existence, insist → insistence. A hard c or g before the ending usually means <b>a</b>: significant, elegant; a soft c or g usually means <b>e</b>: innocent, intelligent.", "ex": ["existence", "interference", "significant", "intelligent", "independent"], "warn": "Keep each family consistent: independent → independence, relevant → relevance, important → importance."},
 {"h": "Plurals: -s, -es, -ies, -ves", "body": "Add <b>-es</b> after s, x, z, ch, sh: buses, boxes, churches, wishes. Consonant + y → <b>-ies</b>: city → cities. Many words in <b>-f / -fe</b> → <b>-ves</b>: knife → knives, life → lives, half → halves.", "ex": ["churches", "cities", "knives", "halves", "boxes"], "warn": "Academic words keep their Latin or Greek plurals: criterion → criteria, phenomenon → phenomena, analysis → analyses, hypothesis → hypotheses."},
 {"h": "Silent letters", "body": "Many common words contain letters you don't hear: <b>k</b>nife, <b>w</b>rite, de<b>b</b>t, dou<b>b</b>t, i<b>s</b>land, recei<b>p</b>t, <b>p</b>sychology, mus<b>c</b>le, forei<b>g</b>n, Wed<b>n</b>esday, autum<b>n</b>, ans<b>w</b>er. Say them in your head as they are written (\"Wed-nes-day\") when you spell.", "ex": ["receipt", "psychology", "muscle", "autumn", "answer"], "warn": ""},
 {"h": "-ise or -ize?", "body": "British English allows both <b>-ise</b> and <b>-ize</b> (organise/organize); American English uses <b>-ize</b>. IELTS accepts either: just be consistent in one essay. Some words are always <b>-ise</b>: advertise, advise, compromise, exercise, surprise, supervise, televise.", "ex": ["organise", "recognise", "advertise", "surprise", "exercise"], "warn": "Analyse (British) / analyze (American): always -yse in British English."},
 {"h": "Prefixes don't change the root", "body": "When you add a prefix, just join it: <b>dis</b> + appear = disappear (one s), <b>dis</b> + satisfied = dissatisfied (two s's), <b>mis</b> + spell = misspell, <b>un</b> + necessary = unnecessary, <b>ir</b> + relevant = irrelevant, <b>im</b> + mature = immature.", "ex": ["disappear", "dissatisfied", "misspell", "unnecessary", "irrelevant"], "warn": "Use im- before b, m, p (impossible, immature), il- before l (illegal), ir- before r (irregular)."},
 {"h": "British vs American spelling", "body": "Choose one variety and stay consistent. British: colour, favour, centre, theatre, travelling, programme, defence, licence (noun), grey, catalogue. American: color, favor, center, theater, traveling, program, defense, license, gray, catalog.", "ex": ["colour", "centre", "programme", "defence", "travelling"], "warn": "IELTS accepts both, but mixing them in one essay looks careless."},
]

